templateCSS:
#fof-faculty-profile {--fp-green:#126045;--fp-deep:#163e30;--fp-gold:#ac8745;--fp-line:#e5eae7;--fp-soft:#f3f7f4;--fp-ink:#333333;--fp-muted:#666666;font-family:"PingFang TC","Microsoft JhengHei",Arial,sans-serif;color:var(--fp-ink);background:#fff;font-size:14px;line-height:1.8;clear:both;text-align:left;}
#fof-faculty-profile *{box-sizing:border-box;}
#fof-faculty-profile button{cursor:pointer;}
#fof-faculty-profile a{color:var(--fp-green);text-decoration:none;overflow-wrap:anywhere;}
#fof-faculty-profile a:hover{text-decoration:underline;}
#fof-faculty-profile .fp-wrap{padding:24px 0 36px;}
#fof-faculty-profile .fp-layout{display:grid;grid-template-columns:230px minmax(0,1fr);gap:34px;align-items:start;}
#fof-faculty-profile .fp-profile{background:var(--fp-soft);border-radius:5px;padding:24px 20px 20px;border-top:3px solid var(--fp-green);}
#fof-faculty-profile .fp-portrait{width:100%;aspect-ratio:1/1.08;object-fit:cover;object-position:center center;display:block;background:#fff;border-radius:8px;margin-bottom:0;}
#fof-faculty-profile .fp-profile h1{font-size:32px;line-height:1.3;margin:0 0 4px;color:var(--fp-deep);font-weight:700;letter-spacing:4px;}
#fof-faculty-profile .fp-en{font-size:14px;letter-spacing:1.5px;color:var(--fp-muted);margin-bottom:14px;}
#fof-faculty-profile .fp-title{font-size:15px;font-weight:700;line-height:1.8;margin:0;}

#fof-faculty-profile .fp-contact{border-top:1px solid #dce5de;margin-top:20px;padding-top:16px;display:grid;gap:12px;}
#fof-faculty-profile .fp-label{font-size:11px;letter-spacing:.8px;display:block;color:var(--fp-muted);line-height:1.5;}
#fof-faculty-profile .fp-contact p{font-size:13px;margin:0;line-height:1.7;}
#fof-faculty-profile .fp-contact a{font-size:12px;}
#fof-faculty-profile .fp-ids{margin-top:24px;}
#fof-faculty-profile .fp-sideheading{font-size:13px;font-weight:700;margin:0 0 10px;color:var(--fp-deep);}
#fof-faculty-profile .fp-id{padding:12px 0;border-bottom:1px solid var(--fp-line);display:block;transition:padding-left .2s ease;}
#fof-faculty-profile .fp-id:hover{padding-left:4px;text-decoration:none;}
#fof-faculty-profile .fp-id strong{font-size:11px;letter-spacing:.6px;display:block;font-weight:700;color:var(--fp-green);}
#fof-faculty-profile .fp-id span{font-size:12px;color:var(--fp-muted);}
#fof-faculty-profile .fp-main{min-width:0;}
#fof-faculty-profile .fp-heading{font-size:25px;line-height:1.4;font-weight:700;color:var(--fp-deep);margin:0 0 20px;}
#fof-faculty-profile .fp-intro{font-size:14px;margin:0 0 12px;line-height:1.95;}
#fof-faculty-profile .fp-nav{display:flex;flex-wrap:wrap;gap:5px 22px;border-top:1px solid var(--fp-line);border-bottom:1px solid var(--fp-line);padding:10px 0;margin:22px 0 28px;}
#fof-faculty-profile .fp-nav button{font:inherit;font-size:13px;font-weight:700;padding:6px 0;border:0;border-bottom:2px solid transparent;background:none;color:var(--fp-muted);}
#fof-faculty-profile .fp-nav button:hover,#fof-faculty-profile .fp-nav button[aria-pressed="true"]{border-bottom-color:var(--fp-gold);color:var(--fp-green);}
#fof-faculty-profile .fp-section{margin:0 0 28px;scroll-margin-top:18px;}
#fof-faculty-profile .fp-section h3{margin:0 0 16px;font-size:18px;color:var(--fp-deep);display:flex;align-items:center;gap:10px;font-weight:700;}
#fof-faculty-profile .fp-section h3::before{content:"";width:3px;height:18px;background:var(--fp-gold);flex-shrink:0;}
#fof-faculty-profile .fp-pair{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:28px 0 4px;}
#fof-faculty-profile .fp-list{list-style:none;margin:0;padding:0;display:grid;gap:10px;font-size:14px;}
#fof-faculty-profile .fp-list li{padding-left:15px;position:relative;}
#fof-faculty-profile .fp-list li::before{content:"";width:4px;height:4px;background:#a8bbaf;position:absolute;left:0;top:11px;border-radius:50%;}
#fof-faculty-profile .fp-tags{display:flex;flex-wrap:wrap;gap:8px;list-style:none;margin:0;padding:0;}
#fof-faculty-profile .fp-tags li{font-size:13px;font-weight:700;color:var(--fp-green);background:var(--fp-soft);padding:6px 12px;border-radius:3px;}
#fof-faculty-profile .fp-line{height:1px;background:var(--fp-line);margin:4px 0 27px;}
#fof-faculty-profile .fp-career{display:grid;grid-template-columns:100px minmax(0,1fr);gap:8px 16px;font-size:14px;}
#fof-faculty-profile .fp-year{font-size:12px;color:var(--fp-gold);font-weight:700;}
#fof-faculty-profile .fp-career small{display:block;font-size:12px;color:var(--fp-muted);margin-bottom:10px;}
#fof-faculty-profile .fp-paper{display:grid;grid-template-columns:42px minmax(0,1fr);gap:14px;padding:17px 0;border-top:1px solid var(--fp-line);}
#fof-faculty-profile .fp-paper time{font-size:12px;color:var(--fp-gold);font-weight:700;}
#fof-faculty-profile .fp-paper p{margin:0 0 5px;font-size:12px;color:var(--fp-muted);line-height:1.7;}
#fof-faculty-profile .fp-paper h4{font-size:14px;line-height:1.65;color:var(--fp-ink);margin:0 0 6px;font-weight:700;}
#fof-faculty-profile .fp-journal{font-size:12px;color:var(--fp-green);line-height:1.7;}
#fof-faculty-profile .fp-meta{font-size:11px;line-height:1.7;color:var(--fp-muted);margin-top:3px;}
@media(max-width:740px){#fof-faculty-profile .fp-wrap{padding:20px;}#fof-faculty-profile .fp-layout{grid-template-columns:190px minmax(0,1fr);gap:24px;}#fof-faculty-profile .fp-profile{padding:18px 14px;}#fof-faculty-profile .fp-pair{grid-template-columns:1fr;gap:0;}}
@media(max-width:570px){#fof-faculty-profile .fp-layout{grid-template-columns:1fr;}#fof-faculty-profile .fp-profile{display:grid;grid-template-columns:116px minmax(0,1fr);gap:0 18px;padding:18px;}#fof-faculty-profile .fp-photo-frame{grid-row:1/5;margin:0;}#fof-faculty-profile .fp-profile h1{font-size:28px;}#fof-faculty-profile .fp-en{margin-bottom:7px;font-size:12px;}#fof-faculty-profile .fp-title{font-size:13px;}#fof-faculty-profile .fp-contact{grid-column:1/-1;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px;padding-top:14px;}#fof-faculty-profile .fp-contact p:first-child{grid-column:1/-1;}#fof-faculty-profile .fp-ids{margin-top:16px;}#fof-faculty-profile .fp-ids-inner{display:flex;gap:6px 22px;flex-wrap:wrap;}#fof-faculty-profile .fp-sideheading{margin-bottom:0;}#fof-faculty-profile .fp-id{border-bottom:0;padding:6px 0;}#fof-faculty-profile .fp-heading{font-size:23px;}#fof-faculty-profile .fp-wrap{padding:18px;}#fof-faculty-profile .fp-nav{gap:4px 17px;}#fof-faculty-profile .fp-career{grid-template-columns:85px 1fr;gap:8px 10px;}}
@media(prefers-reduced-motion:reduce){#fof-faculty-profile *{transition:none!important;scroll-behavior:auto!important;}}

#fof-faculty-profile .fp-main p {text-align:left;}
#fof-faculty-profile .fp-main .fp-intro {text-align:justify;text-justify:inter-ideograph;}
#fof-faculty-profile .fp-list,#fof-faculty-profile .fp-tags {list-style:none;margin-left:0;}
#fof-faculty-profile .fp-profile h1,#fof-faculty-profile .fp-heading,#fof-faculty-profile .fp-section h3,#fof-faculty-profile .fp-paper h4 {text-align:left;border:0;background:none;padding:0;}
#fof-faculty-profile .fp-portrait {float:none;border:0;max-width:100%;}
#fof-faculty-profile .fp-contact a {font-weight:400;}
#fof-faculty-profile .fp-nav button {cursor:pointer;}
#fof-faculty-profile .fp-nav button:focus-visible,#fof-faculty-profile a:focus-visible {outline:2px solid #126045;outline-offset:4px;}
#fof-faculty-profile [hidden] {display:none;}
#fof-faculty-profile .fp-qualifications {margin-top:0;margin-bottom:0;}
#fof-faculty-profile .fp-qualifications .fp-career {grid-template-columns:82px minmax(0,1fr);gap:8px 12px;}

#fof-faculty-profile .fp-photo-frame {margin:0 0 20px;padding:3px;border:3px solid #eeeeee;border-radius:14px;background:#ffffff;overflow:hidden;}
#fof-faculty-profile .fp-supervision {margin-top:12px;}
#fof-faculty-profile .fp-supervisor-tag {display:inline-block;padding:3px 12px;border-radius:10px;background:#e8f3ed;color:#126045;font-size:12px;line-height:1.7;font-weight:700;}
#fof-faculty-profile .fp-papers-scroll {max-height:520px;overflow-y:auto;overflow-x:hidden;scrollbar-gutter:stable;scrollbar-width:auto;scrollbar-color:#9aada3 #eef3f0;padding:0 12px 0 0;}
#fof-faculty-profile .fp-papers-scroll:focus-visible {outline:2px solid #126045;outline-offset:4px;}
#fof-faculty-profile .fp-papers-scroll::-webkit-scrollbar {width:12px;}
#fof-faculty-profile .fp-papers-scroll::-webkit-scrollbar-track {background:#eef3f0;border-radius:8px;}
#fof-faculty-profile .fp-papers-scroll::-webkit-scrollbar-thumb {background:#9aada3;border:2px solid #eef3f0;border-radius:8px;}
#fof-faculty-profile .fp-papers-scroll::-webkit-scrollbar-thumb:hover {background:#748d7f;}
@media(max-width:570px) {
#fof-faculty-profile .fp-supervision {margin-top:8px;}
#fof-faculty-profile .fp-supervisor-tag {padding:2px 10px;}
#fof-faculty-profile .fp-papers-scroll {max-height:420px;}
}
@media(max-width:570px) {#fof-faculty-profile .fp-photo-frame {margin:0;}}
